11	// Author: Gu, Zihan
12	// Description:FN_MUL -> (zeroext, zeroext),
13	//             FN_MULH-> (signext, signext),
14	//             FN_MULHSU -> (signext, zeroext),
15	//             FN_MULHU -> (zeroext, zeroext),
16	//             乘加中都是无符号数乘法
17	
18	`timescale 1ns/1ns
19	`include "define.v"
20	//`include "IDecode_define.v"
21	
22	module array_multiplier #(
23	  parameter LATENCY = 2
24	  )(
25	  input                                       clk            ,
26	  input                                       rst_n          ,
27	
28	  input   [`NUM_THREAD-1:0]                   mask_i         ,
29	  input   [`XLEN-1:0]                         a_i            ,
30	  input   [`XLEN-1:0]                         b_i            ,
31	  input   [`XLEN-1:0]                         c_i            ,
32	  input   [5:0]                               ctrl_alu_fn_i  ,
33	  input   [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]   ctrl_reg_idxw_i,
34	  input   [`DEPTH_WARP-1:0]                   ctrl_wid_i     ,
35	  input                                       ctrl_wvd_i     ,
36	  input                                       ctrl_wxd_i     ,
37	
38	  input                                       in_valid_i     ,
39	  input                                       out_ready_i    ,
40	
41	  output                                      in_ready_o     ,
42	  output                                      out_valid_o    ,
43	
44	  output     [`NUM_THREAD-1:0]                mask_o         ,
45	  output     [5:0]                            ctrl_alu_fn_o  ,
46	  output     [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]ctrl_reg_idxw_o,
47	  output     [`DEPTH_WARP-1:0]                ctrl_wid_o     ,
48	  output                                      ctrl_wvd_o     ,
49	  output                                      ctrl_wxd_o     ,
50	  output reg [`XLEN-1:0]                      result_o     
51	  );
52	
53	  wire    [`XLEN-1:0]                         mul_in1        ;
54	  wire    [`XLEN-1:0]                         mul_in2        ;
55	  wire    [`XLEN-1:0]                         mul_in3        ;
56	  wire    [`XLEN:0]                           signext_mul_in1;//符号位扩展1位后的输入
57	  wire    [`XLEN:0]                           signext_mul_in2;
58	  wire    [`XLEN:0]                           zeroext_mul_in1;
59	  wire    [`XLEN:0]                           zeroext_mul_in2;
60	  wire    [`XLEN:0]                           ai             ;//booth乘法单元输入
61	  wire    [`XLEN:0]                           bi             ;
62	  wire    [2*`XLEN-1:0]                       mul_result     ;
63	
64	  //pipelinereg:latency=2
65	  reg                                         in_valid_reg1  ;
66	  reg                                         in_valid_reg2  ;
67	  wire                                        reg_en1        ;
68	  wire                                        reg_en2        ;
69	
70	  reg     [5:0]                               ctrlvec_alu_fn    ;
71	  reg     [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]   ctrlvec_reg_idwx  ;
72	  reg     [`DEPTH_WARP-1:0]                   ctrlvec_wid       ;
73	  reg                                         ctrlvec_wvd       ;
74	  reg                                         ctrlvec_wxd       ;
75	  reg     [`NUM_THREAD-1:0]                   maskvec_mask      ;
76	  reg     [`XLEN-1:0]                         cvec_mul_in3      ;
77	
78	  reg     [5:0]                               ctrlvec_alu_fn_reg    ;
79	  reg     [`REGIDX_WIDTH+`REGEXT_WIDTH-1:0]   ctrlvec_reg_idwx_reg  ;
80	  reg     [`DEPTH_WARP-1:0]                   ctrlvec_wid_reg       ;
81	  reg                                         ctrlvec_wvd_reg       ;
82	  reg                                         ctrlvec_wxd_reg       ;
83	  reg     [`NUM_THREAD-1:0]                   maskvec_mask_reg      ;
84	
85	  wire    [5:0]                               func              ;
86	  wire    [2*`XLEN-1:0]                       mac_out           ;
87	  wire    [`XLEN-1:0]                         res               ;
88	  wire                                        ismac             ;
89	
90	  assign mul_in1 = (ctrl_alu_fn_i == `FN_MADD | ctrl_alu_fn_i == `FN_NMSUB) ? c_i : a_i;
91	  assign mul_in2 = b_i;
92	  assign mul_in3 = (ctrl_alu_fn_i == `FN_MADD | ctrl_alu_fn_i == `FN_NMSUB) ? a_i : c_i;
93	  //符号位扩展
94	  assign signext_mul_in1 = {mul_in1[`XLEN-1],mul_in1};
95	  assign signext_mul_in2 = {mul_in2[`XLEN-1],mul_in2};
96	  assign zeroext_mul_in1 = {1'b0,mul_in1};
97	  assign zeroext_mul_in2 = {1'b0,mul_in2};
98	
99	  //booth乘法单元输入
100	  assign ai = (ctrl_alu_fn_i == `FN_MULH | ctrl_alu_fn_i == `FN_MULHSU) ? signext_mul_in1 : zeroext_mul_in1;
101	  assign bi = ctrl_alu_fn_i == `FN_MULH ? signext_mul_in2 : zeroext_mul_in2;
102	
103	  //例化booth乘法单元
104	  mult_32 #(
105	    .WORDLEN(`XLEN)
106	  )
107	  U_mul (
108	              .clk   (clk       ),
109	              .rst_n (rst_n     ),
110	              
111	              .Asign (ai        ),
112	              .Bsign (bi        ),
113	              
114	              .Result(mul_result)
115	             );
116	  //pipeline_reg
117	  always@(posedge clk or negedge rst_n) begin
118	    if(!rst_n) begin
119	      in_valid_reg1 <= 'd0 ;
120	      in_valid_reg2 <= 'd0 ;
121	    end
122	    else begin
123	      if(!(!out_ready_i && in_valid_reg1 && in_valid_reg2)) begin
124	        in_valid_reg1 <= in_valid_i   ;
125	      end
126	      else begin
127	        in_valid_reg1 <= in_valid_reg1;
128	      end
129	      if(!(!out_ready_i && in_valid_reg2)) begin        
130	        in_valid_reg2 <= in_valid_reg1;
131	      end
132	      else begin
133	        in_valid_reg2 <= in_valid_reg2;
134	      end
135	    end
136	  end
137	
138	  assign reg_en1 = in_valid_i && !(in_valid_reg1 && in_valid_reg2 && !out_ready_i) ;
139	  assign reg_en2 = in_valid_reg1 && !(in_valid_reg2 && !out_ready_i)               ;
140	
141	  //for valid and ready
142	  assign in_ready_o  = !(!out_ready_i && in_valid_reg1 && in_valid_reg2) ;
143	  assign out_valid_o = in_valid_reg2                                     ;
144	
145	  //pipeline_reg(1)
146	  always@(posedge clk or negedge rst_n) begin
147	    if(!rst_n) begin
148	      ctrlvec_alu_fn   <= 'd0;
149	      ctrlvec_reg_idwx <= 'd0;
150	      ctrlvec_wid      <= 'd0;
151	      ctrlvec_wvd      <= 'd0;
152	      ctrlvec_wxd      <= 'd0;
153	      maskvec_mask     <= 'd0;
154	      cvec_mul_in3     <= 'd0;
155	    end
156	    else if(reg_en1) begin
157	      ctrlvec_alu_fn   <= ctrl_alu_fn_i  ;
158	      ctrlvec_reg_idwx <= ctrl_reg_idxw_i;
159	      ctrlvec_wid      <= ctrl_wid_i     ;
160	      ctrlvec_wvd      <= ctrl_wvd_i     ;
161	      ctrlvec_wxd      <= ctrl_wxd_i     ;
162	      maskvec_mask     <= mask_i         ;
163	      cvec_mul_in3     <= mul_in3        ;
164	    end
165	    else begin
166	      ctrlvec_alu_fn   <= ctrlvec_alu_fn  ;
167	      ctrlvec_reg_idwx <= ctrlvec_reg_idwx;
168	      ctrlvec_wid      <= ctrlvec_wid     ;
169	      ctrlvec_wvd      <= ctrlvec_wvd     ;
170	      ctrlvec_wxd      <= ctrlvec_wxd     ;
171	      maskvec_mask     <= maskvec_mask    ;
172	      cvec_mul_in3     <= cvec_mul_in3    ;
173	    end
174	  end
175	
176	  //pipeline_reg(2)
177	  always@(posedge clk or negedge rst_n) begin
178	    if(!rst_n) begin
179	      ctrlvec_alu_fn_reg   <= 'd0;
180	      ctrlvec_reg_idwx_reg <= 'd0;
181	      ctrlvec_wid_reg      <= 'd0;
182	      ctrlvec_wvd_reg      <= 'd0;
183	      ctrlvec_wxd_reg      <= 'd0;
184	      maskvec_mask_reg     <= 'd0;
185	    end
186	    else if(reg_en2) begin
187	      ctrlvec_alu_fn_reg   <= ctrlvec_alu_fn  ;
188	      ctrlvec_reg_idwx_reg <= ctrlvec_reg_idwx;
189	      ctrlvec_wid_reg      <= ctrlvec_wid     ;
190	      ctrlvec_wvd_reg      <= ctrlvec_wvd     ;
191	      ctrlvec_wxd_reg      <= ctrlvec_wxd     ;
192	      maskvec_mask_reg     <= maskvec_mask    ;
193	    end
194	    else begin
195	      ctrlvec_alu_fn_reg   <= ctrlvec_alu_fn_reg  ;
196	      ctrlvec_reg_idwx_reg <= ctrlvec_reg_idwx_reg;
197	      ctrlvec_wid_reg      <= ctrlvec_wid_reg     ;
198	      ctrlvec_wvd_reg      <= ctrlvec_wvd_reg     ;
199	      ctrlvec_wxd_reg      <= ctrlvec_wxd_reg     ;
200	      maskvec_mask_reg     <= maskvec_mask_reg    ;
201	    end
202	  end
203	
204	
205	  assign func    = ctrlvec_alu_fn;
206	  assign mac_out = (func == `FN_MACC | func == `FN_MADD) ? (mul_result + {{`XLEN{1'b0}},cvec_mul_in3}) : ({{`XLEN{1'b0}},cvec_mul_in3} - mul_result);
207	  assign ismac   = func[4:2] == 3'b110; 
208	  assign res     = ismac ? mac_out[`XLEN-1:0] : ((func == `FN_MULH | func == `FN_MULHU | func == `FN_MULHSU) ? mul_result[2*`XLEN-1:`XLEN] : mul_result[`XLEN-1:0]);
209	
210	  always@(posedge clk or negedge rst_n) begin
211	    if(!rst_n) begin
212	      result_o <= 'd0;
213	    end
214	    else if(reg_en2) begin
215	      result_o <= res;
216	    end
217	    else begin
218	      result_o <= result_o;
219	    end
220	  end
221	
222	  assign ctrl_alu_fn_o   = ctrlvec_alu_fn_reg  ;
223	  assign ctrl_reg_idxw_o = ctrlvec_reg_idwx_reg;
224	  assign ctrl_wid_o      = ctrlvec_wid_reg     ;
225	  assign ctrl_wvd_o      = ctrlvec_wvd_reg     ;
226	  assign ctrl_wxd_o      = ctrlvec_wxd_reg     ;
227	  assign mask_o          = maskvec_mask_reg    ;
228	
229	endmodule
