247			.in_13({{7{B_carry_13}}, B_res_13, 1'b0, B_carry_12, 22'b0}),
248			.in_14({{5{B_carry_14}}, B_res_14, 1'b0, B_carry_13, 24'b0}),
249			.in_15({{3{B_carry_15}}, B_res_15, 1'b0, B_carry_14, 26'b0}),
250			.in_16({B_carry_16, B_res_16, 1'b0, B_carry_15, 28'b0}),
251			.in_17({B_res_17[31:0], 1'b0, B_carry_16, 30'b0}),
252			.in_18({31'b0, B_carry_17, 32'b0}),
253			.out(Result_abs)
254		);
255	
256	  assign Result = (/*Asign_reg*/Asign[WORDLEN] ^ /*Bsign_reg*/Bsign[WORDLEN]) ? ~Result_abs+1 : Result_abs;
257	
258		`ifdef FORMAL
259			assert property(A * B == Result);
260		`endif
261	endmodule
