9	 * MERCHANTABILITY OR FIT FOR A PARTICULAR PURPOSE.
10	 * See the Mulan PSL v2 for more details. */
11	// Author: Gu, Zihan
12	// Description:scalar alu
13	`timescale 1ns/1ns
14	`include "define.v"
15	module  alu #(
16	  parameter DATA_WIDTH    = 32,
17	  parameter OPCODE_WIDTH  = 5
18	  )
19	  (
20	  //input                         clk,
21	  //input                         rst_n,
22	  input     [OPCODE_WIDTH-1:0]  op_i,
23	  input     [`XLEN-1:0]    in1_i,
24	  input     [`XLEN-1:0]    in2_i,
25	  //input     [`XLEN-1:0]    in3_i,
26	
27	  output    [`XLEN-1:0]    out_o,
28	  output                        cmp_o
29	  );
30	
31	  localparam  FN_ADD    = 5'd0;
32	  localparam  FN_SL     = 5'd1;
33	  localparam  FN_SEQ    = 5'd2;
34	  localparam  FN_SNE    = 5'd3;
35	  localparam  FN_XOR    = 5'd4;
36	  localparam  FN_SR     = 5'd5;
37	  localparam  FN_OR     = 5'd6;
38	  localparam  FN_AND    = 5'd7;
39	  localparam  FN_SUB    = 5'd10;
40	  localparam  FN_SRA    = 5'd11;
41	  localparam  FN_SLT    = 5'd12;
42	  localparam  FN_SGE    = 5'd13;
43	  localparam  FN_SLTU   = 5'd14;
44	  localparam  FN_SGEU   = 5'd15;
45	  localparam  FN_MAX    = 5'd16;
46	  localparam  FN_MIN    = 5'd17;
47	  localparam  FN_MAXU   = 5'd18;
48	  localparam  FN_MINU   = 5'd19;
49	  localparam  FN_A1ZERO = 5'd8;
50	  localparam  FN_A2ZERO = 5'd9;
51	  localparam  FN_MUL    = 5'd20;
52	  localparam  FN_MULH   = 5'd21;
53	  localparam  FN_MULHU  = 5'd22;
54	  localparam  FN_MULHSU = 5'd23;
55	  localparam  FN_MACC   = 5'd24;
56	  localparam  FN_NMSAC  = 5'd25;
57	  localparam  FN_MADD   = 5'd26;
58	  localparam  FN_NMSUB  = 5'd27;
59	
60	  wire        isSub;
61	  wire        isCmp;
62	  wire        cmpUnsigned;
63	  wire        cmpInverted;//>
64	  wire        cmpEq;
65	  wire        isMIN;
66	  //wire        isMUL;
67	  //wire        isMAC;//Multiply Accumulate
68	  
69	  wire  [`XLEN-1:0]    in1_rev;
70	  wire  [`XLEN-1:0]    in2_inv;
71	  wire  [`XLEN-1:0]    adder_out;//result of add/sub
72	  wire  [`XLEN-1:0]    in1_xor_in2;
73	  wire                 slt;//result of slt/sltu
74	  wire                 sge;//result of sge/sgeu
75	  wire  [OPCODE_WIDTH-1:0]  shamt;
76	  wire  [`XLEN-1:0]    shin;
77	  wire  [`XLEN-1:0]    shout;//result of sll/srl/sra
78	  wire  [`XLEN-1:0]    shout_l;//result of sll
79	  wire  [`XLEN-1:0]    shout_r;//result of srl/sra
80	  wire  [2*`XLEN-1:0]  shout_r64;
81	  wire  [`XLEN-1:0]    and_or_xor;//result of and/or/xor
82	  wire  [`XLEN-1:0]    shift_logic_cmp;//shift:sll/srl/sra       logic:and/or/xor      cmp:slt/sltu/sge/sgeu
83	  wire  [`XLEN-1:0]    out;//reslut of shift/logic/cmp/seq/sne/add/sub
84	  wire  [`XLEN-1:0]    minu;//unsigned min
85	  wire  [`XLEN-1:0]    maxu;//unsigned max
86	  wire  [`XLEN-1:0]    in1s;//signed in1
87	  wire  [`XLEN-1:0]    in2s;//signed in2
88	  wire  [`XLEN-1:0]    mins;//signed min
89	  wire  [`XLEN-1:0]    maxs;//signed max
90	  wire  [`XLEN-1:0]    minmaxout;//result of min/max
91	  wire                 signed_flag;
92	    
93	
94	  assign  isSub = (op_i >= FN_SUB) & (op_i <= FN_SGEU);
95	  assign  isCmp = (op_i >= FN_SLT) & (op_i <= FN_SGEU);
96	  assign  cmpUnsigned = op_i[1];
97	  assign  cmpInverted = op_i[0];
98	  assign  cmpEq = ~op_i[3];
99	  assign  isMIN = (op_i[4:2] == 3'b100);
100	  //assign  isMUL = (op_i[4:2] == 3'b101);
101	  //assign  isMAC = (op_i[4:2] == 3'b110);
102	
103	  //ADD,SUB
104	  assign  in2_inv = isSub ? (~in2_i) : in2_i;
105	  assign  adder_out = in1_i + in2_inv + isSub;
106	  assign  in1_xor_in2 = in1_i ^ in2_inv;
107	
108	  //SLT,SLTU
109	  assign  slt = (in1_i[`XLEN-1] == in2_i[`XLEN-1]) ? adder_out[`XLEN-1] : 
110	                (cmpUnsigned ? in2_i[`XLEN-1] : in1_i[`XLEN-1]);
111	  assign  sge = ~slt;
112	  assign  cmp_o = cmpInverted ^ (cmpEq ? (in1_xor_in2 == 0) : slt);
113	
114	  //SLL,SRL,SRA
115	  assign  shamt = in2_i[4:0];
116	
117	  genvar i;
118	  generate
119	    for(i=0;i<`XLEN;i=i+1) begin : reverse1
120	      assign in1_rev[i] = in1_i[`XLEN-1-i];
121	    end
122	  endgenerate
123	
124	  assign  shin = (op_i == FN_SR | op_i == FN_SRA) ? in1_i : in1_rev;
125	  assign  shout_r64 = ({{`XLEN{isSub & shin[`XLEN-1]}},shin} >> shamt);
126	  assign  shout_r = shout_r64[`XLEN-1:0];
127	
128	  genvar j;
129	  generate
130	    for(j=0;j<`XLEN;j=j+1) begin : reverse2
131	      assign  shout_l[j] = shout_r[`XLEN-1-j];
132	    end
133	  endgenerate
134	  
135	  assign  shout = ((op_i == FN_SR | op_i == FN_SRA) ? shout_r : 0) | 
136	                  (op_i == FN_SL ? shout_l : 0);
137	
138	  //AND,OR,XOR
139	  assign  and_or_xor = (op_i == FN_XOR) ? in1_i ^ in2_i :
140	                       ((op_i == FN_OR) ? in1_i | in2_i :
141	                       ((op_i == FN_AND) ? in1_i & in2_i : 0));
142	  
143	  assign  shift_logic_cmp = ({{(`XLEN-1){1'b0}},isCmp} & ((op_i == FN_SLT || op_i == FN_SLTU) ? {{(`XLEN-1){1'b0}},slt} : {{(`XLEN-1){1'b0}},sge})) | and_or_xor | shout;
144	
145	  assign  out = (op_i == FN_ADD | op_i == FN_SUB) ? adder_out :
146	                (op_i == FN_SEQ ? in1_i == in2_i : 
147	                (op_i == FN_SNE ? in1_i != in2_i : shift_logic_cmp));
148	  
149	  assign mins = ($signed(in1_i) > $signed(in2_i)) ? in2_i : in1_i;
150	  assign maxs = ($signed(in1_i) > $signed(in2_i)) ? in1_i : in2_i;
151	  assign minu = (in1_i > in2_i) ? in2_i : in1_i;
152	  assign maxu = (in1_i > in2_i) ? in1_i : in2_i;
153	  
154	  assign minmaxout = op_i == FN_MIN ? mins : 
155	                    (op_i == FN_MAX ? maxs : 
156	                    (op_i == FN_MINU ? minu : maxu));
157	
158	  assign out_o =  op_i == FN_A1ZERO ? in2_i : 
159	                  (op_i == FN_A2ZERO ? in1_i : 
160	                  (isMIN ? minmaxout : out));
161	
162	endmodule
